// === Tab: mySketch ===
let MAX_PARTICLE_SPEED = 3;
let NB_PARTICLES = 6000;

let noiseZ;
let noiseSpeedZ, stepNoiseXY;
let TP = TWO_PI;
myVector tabParticles[];//array of particles
let c1, c2;

function setup()
{
  createCanvas(1112, 834);
  background(0);
  colorMode(HSB, 255);
	strokeWeight(3);
  initialize();
}

function initialize()
{
  c1 = random(85, 110);
  c2 = random(255 - c1);
  noiseZ = random(123456);
  noiseSpeedZ = random(.005, .015) * (random(1) < .5 ? 1 : -1);
  stepNoiseXY = random(.001, .01);
  tabParticles = new Array(NB_PARTICLES);
  for (i = 0; i < NB_PARTICLES; i++) {
    tabParticles[i] = new myVector();
  }
  background(255);
}

function draw()
{
  fill(255, 89);
  noStroke(); 
  rect(0, 0, width, height);

  noiseZ += noiseSpeedZ;
  for (i = 0; i < NB_PARTICLES; i++){
    tabParticles[i].update();
  }
}

function mousePressed() {
  initialize();
}

function keyPressed() {
  for (i = 0; i < NB_PARTICLES; i++) {
    tabParticles[i] = new myVector();
  }
}

class myVector {
  x, y;
  myColor;

  constructor() {
    initPart();
  }

  function initPart(){
    x = random(width);
    y = random(height);

    let n = noise(x * stepNoiseXY, y * stepNoiseXY, noiseZ);
    myColor = color(c2 + c1 * n, 100, 0);
  }

  function update(){
    var n = (noise(x*stepNoiseXY, y*stepNoiseXY, noiseZ));
    n = map(n, .1, .9, 0, TP);

    x += n*cos(n * TP) * MAX_PARTICLE_SPEED;
    y += n*sin((1-n) * TP) * MAX_PARTICLE_SPEED;

    if ((x < 0) || (x > width) || 
      (y < 0) || (y > height)) {
      initPart();
    }
    stroke(myColor, 80);
    point(x, y);
  }
}

function keyPressed(){
  save('pix.jpg');
}

